data.query:
query Query($product: ProductWhereInput,
  $strategyWhere: ProductStrategyWhereInput,
  $customer: CustomerWhereInput,
  $unit: UnitWhereInput,
  $facility: FacilityWhereInput,
  $location: LocationWhereInput,
  $receipt: ReceiptWhereInput
) {
  product(where: $product) {
    edges {
      node {
        id
        code
        externalId
        productTypeId
        strategies(where: $strategyWhere) {
          edges {
            node {
              id
              strategyProcesses(where: {final: {_eq: true}}) {
                edges {
                  node {
                    id
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  customer(where: $customer) {
    edges {
      node {
        id
        externalId
      }
    }
  }
  unit(where: $unit) {
    edges {
      node {
        id
      }
    }
  }
  location(where: $location) {
    edges {
      node {
        id
        name
        facility {
          externalId
        }
      }
    }
  }
  facility(where: $facility) {
    edges {
      node {
        id
        externalId
      }
    }
  }
  receipt(where: $receipt) {
    edges {
      node {
        id
        number
        externalId
        statusId
        lines {
          edges {
            node {
              id
              number
              externalId
              statusId
              inventories {
                edges {
                  node {
                    id
                    customData
                    inventoryStatusId
                    externalId
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

